import { test, expect } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';
import { TEST_USER_EMAIL, TEST_USER_PASSWORD } from './test-user';

/**
 * A tiny real video (VP8/WebM, 1 frame, 128x128 — generated by
 * scripts/make-e2e-video-fixture.mjs) returned by the mocked video-status
 * endpoint as a `data:` URL. The app turns data: URLs into a local blob for
 * the player (src/hooks/useVideoGeneration.ts), so the completed render
 * requires zero network access.
 */
function mockVideoDataUrl(): string {
  const bytes = fs.readFileSync(path.join(process.cwd(), 'e2e', 'fixtures', 'mock-video.webm'));
  return `data:video/webm;base64,${bytes.toString('base64')}`;
}

test.describe('CreatorOS End-to-End System Smoke Tests', () => {
  test('should authenticate against the Auth emulator and run the full mocked video generation flow', async ({
    page,
  }) => {
    test.setTimeout(90_000);

    // F4.5 guard rails: Firebase runs in local emulators and every /api/* route
    // is mocked below, so any request that would leave the machine is a bug —
    // recorded here and failed at the end of the test.
    const liveFirebaseHits: string[] = [];
    page.on('request', (request) => {
      const url = request.url();
      const isFirebaseDataPlane =
        /firebaseio\.com|identitytoolkit\.googleapis\.com|securetoken\.googleapis\.com|firestore\.googleapis\.com|firebasestorage\.googleapis\.com/.test(
          url,
        );
      if (isFirebaseDataPlane && !url.includes('127.0.0.1')) liveFirebaseHits.push(url);
    });
    const unmockedApiCalls: string[] = [];

    // Catch-all: registered FIRST so the specific mocks below take precedence
    // (Playwright resolves overlapping routes last-registered-first). Anything
    // not explicitly mocked below fails the test instead of leaking live.
    await page.route('**/api/**', (route) => {
      unmockedApiCalls.push(route.request().url());
      return route.abort();
    });

    // Benign mocks for the API routes the app calls on the pages this spec
    // visits. /api/gemini/generate returns { text } (all consumers read
    // data.text); the analytics/onboarding endpoints tolerate empty objects —
    // the components degrade gracefully to empty states.
    await page.route('**/api/gemini/generate', async (route) => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ text: 'E2E mocked Gemini response.' }),
      });
    });
    await page.route('**/api/analytics/summary', async (route) => {
      await route.fulfill({ status: 200, contentType: 'application/json', body: '{}' });
    });
    // Phase A: sign-in now fire-and-forgets the session-cookie exchange; the
    // real endpoint is unit-tested server-side, here it just must not block.
    await page.route('**/api/auth/session', async (route) => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ ok: true, expiresIn: 14 * 24 * 60 * 60 }),
      });
    });
    await page.route('**/api/onboarding/**', async (route) => {
      await route.fulfill({ status: 200, contentType: 'application/json', body: '{}' });
    });

    // 1. Mock the Gemini video generation API, extending the established
    //    video-route pattern: submit → two in-progress polls → completed.
    await page.route('**/api/gemini/generate-video', async (route) => {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ operationName: 'mock-operation-e2e-123' }),
      });
    });

    let statusCheckCount = 0;
    await page.route('**/api/gemini/video-status', async (route) => {
      statusCheckCount++;
      if (statusCheckCount < 3) {
        // First two polls simulate progress
        await route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify({
            done: false,
            progressPercentage: statusCheckCount * 40,
            data: null,
          }),
        });
      } else {
        // Final poll returns complete with the local fixture as a data: URL
        await route.fulfill({
          status: 200,
          contentType: 'application/json',
          body: JSON.stringify({
            done: true,
            progressPercentage: 100,
            data: mockVideoDataUrl(),
          }),
        });
      }
    });

    // 2. Load the landing page
    await page.goto('/');
    await expect(page).toHaveTitle(/CreatorOS/i);

    // Verify presence of primary headers
    const mainHeading = page.locator('h1');
    await expect(mainHeading.first()).toBeVisible();

    // 3. Initiate authentication flow via the primary CTA
    await page.locator('button:has-text("Get Started")').first().click();

    // Confirm we are on the Auth screen
    await expect(page).toHaveURL(/\/login/);

    // 4. Sign in as the emulator-seeded e2e user (F4.5: no real credentials —
    //    the account only exists inside the local Auth emulator).
    const emailInput = page.locator('input[placeholder="Email Address"]');
    const passwordInput = page.locator('input[placeholder="Password"]');

    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();

    await emailInput.fill(TEST_USER_EMAIL);
    await passwordInput.fill(TEST_USER_PASSWORD);
    await page.locator('button[type="submit"]').click();

    // 5. Workspace is mounted directly: global-setup seeds projects/brand_<uid>
    //    (status 'ready'), so the onboarding modal is suppressed and the
    //    Create studio's "Identity Required" gate is unlocked. The app header
    //    only renders for an authenticated user.
    const menuButton = page.locator('header button').first();
    await expect(menuButton).toBeVisible();

    // 6. Navigation to the "Create" Page via the nav drawer (desktop & mobile compatible)
    await menuButton.click();

    // Select the "Create" navigation item inside drawer. D7-A: nav entries are
    // router Links (anchors) now, not buttons. Exact name so "Creator Hub"
    // doesn't match "Create" substring matching.
    const createNavItem = page.getByRole('link', { name: 'Create', exact: true }).first();
    await expect(createNavItem).toBeVisible();
    await createNavItem.click();

    // 7. Verify the Create Workspace loaded successfully
    const scriptEditor = page.locator(
      'textarea[placeholder*="narrative? AI will score your brand voice"]',
    );
    await expect(scriptEditor).toBeVisible();

    // Fill in a sample video script
    await scriptEditor.fill(
      'This is an automated E2E system check verifying Gemini Video generation, layout boundaries, and reactive workflows.',
    );

    // 8. Toggle Gemini Advanced video configuration settings
    const advancedSettingsButton = page.locator('button[title="Advanced Settings"]');
    await expect(advancedSettingsButton).toBeVisible();
    await advancedSettingsButton.click();

    // Check that video properties expanded
    const videoStyleLabel = page.locator('label:has-text("Video Style")');
    await expect(videoStyleLabel).toBeVisible();

    // 9. Trigger Video Generation
    const generateBtn = page.locator('button:has-text("Generate Gemini")');
    await expect(generateBtn).toBeVisible();
    await generateBtn.click();

    // Verify polling loader transitions are active
    const previewHeader = page.locator('span:has-text("Gemini Preview")');
    await expect(previewHeader).toBeVisible();

    // Verify the simulated custom video player has rendered the completed video.
    // The completed video appears in BOTH the Gemini Preview panel and Video
    // History; scope to the preview player so the assertion isn't ambiguous.
    const previewSection = page.locator('section').filter({ hasText: 'Gemini Preview' });
    const videoContainer = previewSection.locator('video');
    await expect(videoContainer).toBeVisible();
    await expect(page.locator('video')).toHaveCount(2); // preview + history entry

    // F4.5 assertions: the entire flow stayed on local emulators and mocks.
    expect(
      unmockedApiCalls,
      `unmocked /api calls reached the network: ${unmockedApiCalls.join(', ')}`,
    ).toEqual([]);
    expect(liveFirebaseHits, `requests hit live Firebase: ${liveFirebaseHits.join(', ')}`).toEqual(
      [],
    );
  });
});
